export const siteConfig = {
  name: "img0",
  url: "https://www.img0.site",
  description: "Free online image tools to convert, compress, crop, and edit images in your browser. Your image files stay on your device, with no uploads.",
  links: { twitter: "https://x.com/img0dotsite" },
  ogImage: "/OG-img0.png",
};

// Match the trailing-slash URLs generated by the static export.
export function canonicalUrl(path = "/"): string {
  const url = new URL(path, siteConfig.url);
  if (!url.pathname.endsWith("/")) url.pathname += "/";
  return url.href;
}
